  "inlineSchema": "// NexaVoice — PostgreSQL data layer (Prisma ORM 7).\n//\n//   • `Client` / `Agent` hold the people who sign in on the /login page.\n//   • `Product` is the fixed NexaMart catalogue (50 items, seeded once). Every\n//     client — new or returning — shops from these rows only.\n//   • `CartItem` is the per-client shopping cart, `Order` / `OrderItem` the\n//     placed orders whose status moves PLACED → ON_THE_WAY → DELIVERED.\n//   • `StoreState` is the durable mirror for the live support store\n//     (conversations, cases, events) — one JSONB document, see\n//     lib/support/snapshot.ts.\n//\n// Push the schema into a running Postgres with `pnpm db:push`, or use a proper\n// migration workflow with `pnpm db:migrate`. The connection string lives in\n// prisma.config.ts (Prisma 7), fed by DATABASE_URL — see env.local.example.\n\ngenerator client {\n  provider = \"prisma-client\"\n  output   = \"../generated/prisma\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n}\n\n/// A customer (\"client\") who signs in on the /login page.\nmodel Client {\n  id                String   @id @default(cuid())\n  name              String\n  email             String\n  phone             String   @unique\n  tier              String   @default(\"standard\") // standard | prime\n  city              String   @default(\"\")\n  address           String   @default(\"\")\n  preferredLanguage String   @default(\"english\") // hindi | english | hinglish\n  createdAt         DateTime @default(now())\n  updatedAt         DateTime @updatedAt\n\n  cart   CartItem[]\n  orders Order[]\n\n  @@index([phone])\n}\n\n/// A human support agent who signs in on the /login page.\nmodel Agent {\n  id        String   @id @default(cuid())\n  name      String\n  email     String   @unique\n  title     String   @default(\"Support Agent\")\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([email])\n}\n\n/// Fixed NexaMart catalogue — the only products a client can buy.\nmodel Product {\n  id          String   @id @default(cuid())\n  sku         String   @unique\n  title       String\n  category    String\n  description String   @default(\"\")\n  priceInr    Int\n  emoji       String   @default(\"🛍️\")\n  imageUrl    String?\n  rating      Float    @default(4.2)\n  /// Short safety note shown on the product card (e.g. medicines).\n  caution     String   @default(\"\")\n  active      Boolean  @default(true)\n  createdAt   DateTime @default(now())\n\n  cartItems  CartItem[]\n  orderItems OrderItem[]\n\n  @@index([category])\n}\n\n/// One product line in a client's cart.\nmodel CartItem {\n  id        String   @id @default(cuid())\n  clientId  String\n  productId String\n  qty       Int      @default(1)\n  addedAt   DateTime @default(now())\n\n  client  Client  @relation(fields: [clientId], references: [id], onDelete: Cascade)\n  product Product @relation(fields: [productId], references: [id], onDelete: Cascade)\n\n  @@unique([clientId, productId])\n  @@index([clientId])\n}\n\n/// A placed order. `status` advances on a timer (see lib/shop/orders.ts):\n/// PLACED → ON_THE_WAY → DELIVERED. Items may only change while PLACED.\nmodel Order {\n  id                 String    @id @default(cuid())\n  /// Human/agent facing order number, e.g. NM-10023.\n  code               String    @unique\n  clientId           String\n  status             String    @default(\"PLACED\") // PLACED | ON_THE_WAY | DELIVERED | CANCELLED\n  totalInr           Int       @default(0)\n  shippingAddress    String\n  paymentMethod      String    @default(\"COD\") // UPI | CARD | COD\n  placedAt           DateTime  @default(now())\n  statusUpdatedAt    DateTime  @default(now())\n  expectedDelivery   DateTime\n  deliveredAt        DateTime?\n  cancelledAt        DateTime?\n  cancellationReason String?\n  /// [{ at: number, event: string }] — order timeline shown to client + agent.\n  history            Json      @default(\"[]\")\n  updatedAt          DateTime  @updatedAt\n\n  client Client      @relation(fields: [clientId], references: [id], onDelete: Cascade)\n  items  OrderItem[]\n\n  @@index([clientId])\n  @@index([status])\n}\n\n/// One product line inside a placed order (price captured at order time).\nmodel OrderItem {\n  id        String @id @default(cuid())\n  orderId   String\n  productId String\n  sku       String\n  title     String\n  qty       Int\n  priceInr  Int\n\n  order   Order   @relation(fields: [orderId], references: [id], onDelete: Cascade)\n  product Product @relation(fields: [productId], references: [id])\n\n  @@unique([orderId, productId])\n  @@index([orderId])\n}\n\n/// Sequence source for human-readable order numbers (NM-10001, NM-10002, …).\nmodel OrderCounter {\n  id    String @id\n  value Int    @default(10000)\n}\n\n/// Durable live-support document (one row): conversations, cases, events.\nmodel StoreState {\n  id        String   @id\n  rev       Int      @default(0)\n  snapshot  Json\n  updatedAt DateTime @updatedAt\n}\n",
